  "a_sentences": [
    {
      "a_text": "Der Streit dreht sich um den Anspruch des Versicherten auf eine Invalidenrente und eine Integritätsentschädigung, insbesondere um die massgeblichen Invaliditäts- und Integritätsschadengrade.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Ein Anspruch auf eine Invalidenrente der Unfallversicherung entsteht erst bei einer Invalidität von mindestens 10 %.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Bei erwerbstätigen Versicherten ist der Invaliditätsgrad durch einen Einkommensvergleich zu ermitteln.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Das mittlere Alter liegt bei 42 Jahren (zwischen 40 und 45 Jahren), während das fortgeschrittene Alter etwa 60 Jahre beträgt; es handelt sich dabei um einen Richtwert ohne absolute Grenze.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Da dem Versicherten zum massgeblichen Zeitpunkt nur noch zwei Jahre bis zur Pensionierung verblieben und dies seine Vermittelbarkeit erheblich einschränkt, ist die Anwendung von Art. 28 Abs. 4 UVV gerechtfertigt.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Das Bundesgericht bestätigt die Anwendung von Art. 28 Abs. 4 UVV und verneint daher die Bemessung des Valideneinkommens anhand der Einkommensmittel der Jahre 2015 bis 2019.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Die Invaliditätsbemessung der Vorinstanz ist im Übrigen nicht zu beanstanden; ein Abzug vom Tabellenlohn für den Invalideneinkommen rechtfertigt sich nicht.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Der Antrag auf eine höhere Integritätsentschädigung wird abgewiesen, da das Gutachten der Suva den von der Vorinstanz festgelegten Wert von 10 % nicht in Frage stellt.",
      "b_propositions": ["P8"]
    }
  ]
}
